using System;using System.Collections.Generic;public class Solution{public int MinTotalDistance(int[][]g){var r=new List<int>();var c=new List<int>();for(int i=0;i<g.Length;i++)for(int j=0;j<g[0].Length;j++)if(g[i][j]==1)r.Add(i);for(int j=0;j<g[0].Length;j++)for(int i=0;i<g.Length;i++)if(g[i][j]==1)c.Add(j);int mr=r[r.Count/2],mc=c[c.Count/2],s=0;foreach(int x in r)s+=Math.Abs(x-mr);foreach(int x in c)s+=Math.Abs(x-mc);return s;}}
